query:
SELECT COLUMN_NAME, COLUMN_TYPE, COLUMN_DEFAULT, IS_NULLABLE 
FROM INFORMATION_SCHEMA.COLUMNS 
WHERE TABLE_NAME = 'leads' AND COLUMN_NAME IN ('noOutboundCalls', 'noOutboundCallsAt');

